+                            <AccessibleButton
+                                element="button"
+                                type="submit"
+                                kind="primary"
+                                onClick={this.onSubmit}
+                                disabled={!this.state.token}
+                            >
+                                {_t("Continue")}
+                            </AccessibleButton>
+                        )}
+                    </div>
+                </form>
+            </div>
+        );
+    }
